import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Poligoni regolari inscritti in una circonferenza","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fr/frb.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fr/frb.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fr/frb.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="poligoni-regolari-inscritti-in-una-circonferenza" tabindex="-1">Poligoni regolari inscritti in una circonferenza <a class="header-anchor" href="#poligoni-regolari-inscritti-in-una-circonferenza" aria-label="Permalink to “Poligoni regolari inscritti in una circonferenza”">​</a></h1><p>Enuncio alcune proprietà senza dimostrazione.</p><p>Abbiamo che: <strong>Dato un qualsiasi poligono regolare è sempre possibile inscriverlo in una circonferenza</strong></p><blockquote><p>In questo caso i raggi dei cerchi coincidono con i lati dei triangoli congruenti in cui possiamo suddividere i vari poligoni regolari congiungendo il centro del cerchio circoscritto con i vertici dei poligoni.</p></blockquote><p>Inoltre avremo che: <strong>All&#39;aumentare del numero dei lati la misura del perimetro di un poligono regolare inscritto in una circonferenza aumenta avvicinandosi alla misura della lunghezza della circonferenza stessa</strong></p><p>Ad esempio, se considero il quadrato inscritto e poi l&#39;ottagono regolare inscritto, avremo che il perimetro dell&#39;ottagono è maggiore del perimetro del quadrato ma minore della lunghezza della circonferenza.</p><p>Per mostrare che la misura della circonferenza è maggiore della misura del perimetro di qualunque poligono inscritto basta ricordare che ogni corda è minore del suo arco.</p><blockquote><p><strong>Esercizio:</strong> Prova a dimostrarlo.</p></blockquote><p>Se considero il lato del quadrato <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">AB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> e i lati dell&#39;ottagono <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>P</mi></mrow><annotation encoding="application/x-tex">AP</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span> e <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">PB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span>, essi formano il triangolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>P</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">APB</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> e in ogni triangolo ogni lato è minore della somma degli altri due, quindi:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>A</mi><mi>B</mi><mo>&lt;</mo><mi>A</mi><mi>P</mi><mo>+</mo><mi>P</mi><mi>B</mi></mrow><annotation encoding="application/x-tex">AB &lt; AP + PB </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span></span></p><p>applicandolo a tutti i lati del quadrato e dell&#39;ottagono ottengo la proprietà.</p>`,11)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};